from pathlib import Path
import json,csv,re,html
from datetime import date
ROOT=Path(__file__).resolve().parents[1]

def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def esc(s): return html.escape(str(s))
def head(title,desc,canonical):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="https://outdoorsteamsauna.com{canonical}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="https://outdoorsteamsauna.com{canonical}"><link rel="stylesheet" href="/assets/style.css"></head><body>'''
def nav(): return '''<header class="top"><div class="wrap nav"><a class="brand" href="/"><span>OSS</span>OutdoorSteamSauna.com</a><nav class="navlinks"><a href="/climate-index/">Climate Index</a><a href="/heater-sizing/">Heater Sizing</a><a href="/operating-cost/">Cost</a><a href="/rankings/">Rankings</a><a href="/guides/steam-vs-sauna/">Steam?</a><a href="/data-download/">Data</a></nav></div></header>'''
def footer(): return '''<footer class="footer"><div class="wrap footer-grid"><div><b>OutdoorSteamSauna.com</b><p>A climate and planning reference for outdoor traditional sauna projects. Data-driven estimates are for planning, not electrical, structural, or code approval.</p></div><div><b>Tools</b><p><a href="/heater-sizing/">Heater sizing</a><br><a href="/operating-cost/">Operating cost</a><br><a href="/climate-index/">Climate index</a></p></div><div><b>Reference</b><p><a href="/methodology/">Methodology</a><br><a href="/data-download/">Download data</a><br><a href="/recommended-retailer/">Where to buy</a></p></div></div></footer><script src="/assets/app.js"></script></body></html>'''
def write(path,body):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body)

data=json.load(open(ROOT/'data/cities.json')); cities=data['cities']; meta=data['meta']; heaters=json.load(open(ROOT/'data/heaters.json'))
# state summary
states={}
for c in cities: states.setdefault(c['state'],[]).append(c)
state_rows=[]
for st,cs in states.items():
 state_rows.append({'state':st,'state_name':cs[0]['state_name'],'avg_score':round(sum(x['metrics']['score'] for x in cs)/len(cs),1),'rate':round(sum(x['metrics']['rate_cents'] for x in cs)/len(cs),2),'cities':len(cs)})
state_rows.sort(key=lambda x:x['avg_score'],reverse=True)

banner='' if not meta.get('starter') else f'''<div class="wrap status"><b>Starter climate dataset.</b> Run the GitHub <b>Update outdoor sauna climate index and deploy</b> workflow to replace preview values with NOAA NCEI climate normals and current EIA electricity rates.</div>'''
rows=''.join(f'''<tr data-city-row="{esc((c['city']+' '+c['state']).lower())}"><td class="rank">#{c['rank']}</td><td><a href="/cities/{c['slug']}/"><b>{esc(c['city'])}, {c['state']}</b></a></td><td class="score">{c['metrics']['score']}</td><td>{c['metrics']['jan_tmin_f']}°F</td><td>{c['metrics']['rate_cents']}¢</td><td>${c['metrics']['session_cost_9kw']:.2f}</td></tr>''' for c in cities[:30])
top=cities[:4]
home=head('Outdoor Sauna Climate Index & Planning Tools','Climate-driven outdoor traditional sauna planning: operating costs, city rankings, heater sizing and downloadable data.','/')+nav()+banner+f'''<section class="hero"><div class="wrap"><div class="eyebrow">U.S. outdoor sauna climate intelligence</div><h1>Plan the heat for the climate outside.</h1><p>Compare outdoor sauna planning load, winter conditions and electricity economics across {len(cities)} U.S. metros. Then size the room, account for glass and estimate operating cost.</p><div class="hero-actions"><a class="btn primary" href="/climate-index/">Explore the index</a><a class="btn" href="/heater-sizing/">Size a heater</a></div></div></section><section class="section"><div class="wrap"><div class="grid"><div class="card stat"><small>METROS INDEXED</small><b>{len(cities)}</b><span class="muted">across {len(states)} states/DC</span></div><div class="card stat"><small>CLIMATE BASELINE</small><b>{meta.get('normal_period','1991–2020')}</b><span class="muted">NOAA normals target</span></div><div class="card stat"><small>LIVE NOAA METROS</small><b>{meta.get('live_noaa_cities',0)}</b><span class="muted">last refresh</span></div><div class="card stat"><small>LIVE EIA STATES</small><b>{meta.get('live_eia_states',0)}</b><span class="muted">electricity rates</span></div></div></div></section><section class="section"><div class="wrap grid"><div class="index-panel"><div class="eyebrow">Climate index</div><h2>Where outdoor heat works hardest.</h2><div class="searchbox"><input id="citySearch" placeholder="Search city or state"></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Metro</th><th>Load score</th><th>Jan low</th><th>Power</th><th>9 kW/session</th></tr></thead><tbody>{rows}</tbody></table></div><p><a class="btn dark" href="/rankings/">View all rankings</a></p></div><aside class="card side-panel calc"><div class="eyebrow">Quick estimator</div><h3>What does a session cost?</h3><form id="costForm"><div class="field"><label>Heater kW<input name="kw" type="number" value="9" step="0.1"></label></div><div class="field"><label>Electricity ¢/kWh<input name="rate" type="number" value="15" step="0.1"></label></div><div class="field"><label>Warm-up minutes<input name="warm" type="number" value="70"></label></div><div class="field"><label>Session minutes<input name="session" type="number" value="60"></label></div><div class="field"><label>Sessions/week<input name="freq" type="number" value="3"></label></div></form><div id="costResult" class="result"></div><p><a class="btn" href="/operating-cost/">Full cost calculator</a></p></aside></div></section><section class="section"><div class="wrap editorial"><div class="eyebrow">Why this exists</div><h2>An outdoor sauna in Miami and one in Minneapolis are not the same planning problem.</h2><p>Outdoor traditional saunas face different warm-up loads, freeze exposure and electricity economics depending on location. This index turns public climate and energy data into standardized planning comparisons rather than pretending one national rule fits every backyard.</p><div class="callout"><b>The score is a planning index, not a building-code or heater-approval tool.</b> Final heater selection, clearances, wiring and installation must follow the current manufacturer instructions and local requirements.</div><p><a href="/methodology/">Read the scoring methodology →</a></p></div></section><section class="section"><div class="wrap grid"><div class="card" style="grid-column:span 7"><div class="eyebrow">Traditional sauna, real steam</div><h2>Yes, water on hot sauna stones creates steam. It still isn't a steam room.</h2><p>The domain reflects how people search. A traditional sauna uses a heater and stones; throwing appropriate water on hot stones creates a temporary humidity burst—löyly. A dedicated steam room is a different high-humidity system and requires different construction.</p><a class="btn dark" href="/guides/steam-vs-sauna/">Read the terminology guide</a></div><div class="card" style="grid-column:span 5"><div class="eyebrow">Buying path</div><h3>Already know you want an outdoor traditional sauna?</h3><p>We keep commerce separate from the data pages. See why we selected one retailer for shoppers looking for premium outdoor traditional sauna kits.</p><a class="btn primary" href="/recommended-retailer/">Recommended retailer →</a></div></div></section>'''+footer()
write('index.html',home)

# climate index page
allrows=''.join(f'''<tr data-city-row="{esc((c['city']+' '+c['state']).lower())}"><td class="rank">#{c['rank']}</td><td><a href="/cities/{c['slug']}/"><b>{esc(c['city'])}, {c['state']}</b></a></td><td>{c['metrics']['score']}</td><td>{c['metrics']['label']}</td><td>{c['metrics']['jan_tmin_f']}°F</td><td>{c['metrics']['freeze_months']}</td><td>{c['metrics']['annual_snow_in']} in</td><td>{c['metrics']['rate_cents']}¢</td></tr>''' for c in cities)
write('climate-index/index.html',head('U.S. Outdoor Sauna Climate Index','Compare outdoor sauna climate planning load across major U.S. metros.','/climate-index/')+nav()+f'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Outdoor Sauna Climate Index</div><h1>{len(cities)} metros, one standardized planning model.</h1><p>Higher scores indicate more challenging outdoor thermal conditions and/or higher electricity cost under the standardized model.</p></div></section><section class="section"><div class="wrap"><div class="searchbox"><input id="citySearch" placeholder="Filter by city or state"></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Metro</th><th>Score</th><th>Class</th><th>Jan low</th><th>Freeze months</th><th>Snow</th><th>Power</th></tr></thead><tbody>{allrows}</tbody></table></div></div></section>'''+footer())

# rankings
rank_blocks=''
for title,arr,explain in [
 ('Highest planning load',cities[:15],'Cold conditions, freeze exposure and electricity rates combine to increase the standardized planning load.'),
 ('Lowest planning load',list(reversed(cities[-15:])),'Milder winter conditions and/or lower electricity rates reduce standardized operating burden.'),
 ('Highest estimated 9 kW session cost',sorted(cities,key=lambda x:x['metrics']['session_cost_9kw'],reverse=True)[:15],'Standardized 9 kW scenario using each state’s electricity rate and climate-adjusted warm-up assumption.'),
 ('Snowiest indexed metros',sorted(cities,key=lambda x:x['metrics']['annual_snow_in'],reverse=True)[:15],'Annual snowfall is included as a site-planning exposure, not as a claim about heater performance.')]:
 trs=''.join(f'''<tr><td>{i}</td><td><a href="/cities/{c['slug']}/">{esc(c['city'])}, {c['state']}</a></td><td>{c['metrics']['score']}</td><td>${c['metrics']['session_cost_9kw']:.2f}</td></tr>''' for i,c in enumerate(arr,1))
 rank_blocks+=f'''<div class="card" style="margin-bottom:24px"><h3>{title}</h3><p>{explain}</p><table><thead><tr><th>#</th><th>Metro</th><th>Score</th><th>9 kW/session</th></tr></thead><tbody>{trs}</tbody></table></div>'''
write('rankings/index.html',head('Outdoor Sauna Rankings','Rankings from the Outdoor Sauna Climate Index, including planning load and standardized operating costs.','/rankings/')+nav()+f'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Rankings</div><h1>Outdoor sauna conditions, ranked.</h1><p>Built from the same methodology used on every city page. Download the underlying dataset for your own analysis.</p></div></section><section class="section"><div class="wrap">{rank_blocks}<a class="btn dark" href="/data-download/">Download the data</a></div></section>'''+footer())

# operating cost page
write('operating-cost/index.html',head('Outdoor Sauna Electricity Cost Calculator','Estimate electricity use and cost for an outdoor electric sauna by heater size, warm-up time and session frequency.','/operating-cost/')+nav()+'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Operating cost calculator</div><h1>Turn heater kW into dollars per session.</h1><p>A transparent scenario calculator for electric traditional saunas. Change every assumption yourself.</p></div></section><section class="section"><div class="wrap grid"><div class="card calc" style="grid-column:span 6"><form id="costForm"><div class="field"><label>Heater output (kW)<input name="kw" type="number" value="9" step="0.1"></label></div><div class="field"><label>Electricity rate (¢/kWh)<input name="rate" type="number" value="15" step="0.1"></label></div><div class="field"><label>Warm-up minutes<input name="warm" type="number" value="70"></label></div><div class="field"><label>Session minutes<input name="session" type="number" value="60"></label></div><div class="field"><label>Sessions per week<input name="freq" type="number" value="3"></label></div></form><div id="costResult" class="result"></div></div><div class="card" style="grid-column:span 6"><h3>What the calculator assumes</h3><p>Warm-up is modeled at full heater output. During the session, the estimator uses a 60% full-load-equivalent duty assumption rather than assuming the heater runs continuously at maximum output.</p><p>Actual thermostat cycling, outdoor temperature, insulation, glass area, ventilation, door openings and user behavior can materially change consumption.</p><p>Use the city pages for climate-adjusted standardized comparisons.</p></div></div></section>'''+footer())

# heater sizing
heater_json=json.dumps(heaters)
heater_table=''.join(f'''<tr><td>{x['brand']}</td><td>{x['model']}</td><td>{x['kw']} kW</td><td>{x['min_ft3']}–{x['max_ft3']} ft³</td><td><a href="{x['source']}" rel="nofollow">manufacturer source</a></td></tr>''' for x in heaters)
write('heater-sizing/index.html',head('Outdoor Sauna Heater Sizing Calculator','Calculate physical and adjusted sauna volume and compare it with published heater room-volume ranges.','/heater-sizing/')+nav()+f'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Heater sizing</div><h1>Size the room before you size the heater.</h1><p>Calculate raw room volume, then account for glass or other uninsulated surfaces before comparing the result with the current heater manufacturer’s rated room-volume range.</p></div></section><section class="section"><div class="wrap grid"><div class="card calc" style="grid-column:span 6"><form id="heaterForm"><div class="field"><label>Interior length (ft)<input name="length" type="number" value="6" step="0.1"></label></div><div class="field"><label>Interior width (ft)<input name="width" type="number" value="6" step="0.1"></label></div><div class="field"><label>Interior height (ft)<input name="height" type="number" value="7" step="0.1"></label></div><div class="field"><label>Glass / uninsulated surface (ft²)<input name="glass" type="number" value="15" step="1"></label></div></form><div id="heaterResult" class="result"></div></div><div class="card" style="grid-column:span 6"><h3>Surface adjustment</h3><p>This planning calculator uses <b>3.3 ft³ of added effective volume per ft² of uninsulated surface</b>, the imperial form of a 1 m³-per-m² approach published in sauna-heater guidance. It is not a universal building code.</p><p>Different heater manufacturers may use different sizing logic. Always use the specific heater’s current manual/calculator for final selection.</p><p><a href="https://huumsauna.com/sauna-heater-size-calculator-how-to-choose-the-right-power-rating-for-your-sauna/" rel="nofollow">HUUM sizing methodology →</a></p></div></div><div class="wrap" style="margin-top:30px"><h2>Published reference ranges</h2><div class="table-wrap"><table><thead><tr><th>Brand</th><th>Model</th><th>Output</th><th>Rated room volume</th><th>Source</th></tr></thead><tbody>{heater_table}</tbody></table></div><p class="data-note">Small reference sample only; not a recommendation that these specific heaters are appropriate for an outdoor installation.</p></div></section><script>window.HEATERS={heater_json}</script>'''+footer())

# guides
write('guides/steam-vs-sauna/index.html',head('Outdoor Steam Sauna vs Traditional Sauna','Understand why a traditional outdoor sauna can create steam from water on hot stones while remaining different from a steam room.','/guides/steam-vs-sauna/')+nav()+'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Terminology</div><h1>Can an outdoor traditional sauna make steam?</h1><p>Yes—if the heater and stones are designed for water. But that does not make the room a steam room.</p></div></section><section class="section"><div class="wrap editorial"><h2>Traditional sauna: heat first, humidity in bursts.</h2><p>A traditional sauna heats the room and a mass of sauna stones. When suitable water is thrown onto those hot stones, it vaporizes and creates a temporary rise in humidity often described by the Finnish word <i>löyly</i>.</p><p>Harvia describes its stone-heavy Cilindro heater as producing different qualities of steam depending on where water is thrown on the stone pillar.</p><h3>A steam room is a different system.</h3><p>A dedicated steam room relies on a steam generator and is designed around sustained very high humidity. That changes waterproofing, surfaces, drainage and construction requirements. Outdoor traditional sauna kits should not be treated as steam-room enclosures unless their manufacturer explicitly says otherwise.</p><div class="callout">Only pour water on a heater/stone setup that the manufacturer permits for that use, and follow the heater’s current operating instructions.</div><p class="source-list"><a href="https://www.harvia.com/en-US/products/HPC900400/cilindro-pc90-90-kw-steel" rel="nofollow">Harvia Cilindro technical reference →</a></p></div></section>'''+footer())
write('guides/outdoor-installation/index.html',head('Outdoor Sauna Installation Planning Guide','A planning checklist for outdoor traditional sauna siting, foundation, weather exposure, drainage and access.','/guides/outdoor-installation/')+nav()+'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Site planning</div><h1>Plan the site before the sauna arrives.</h1></div></section><section class="section"><div class="wrap editorial"><h2>Five constraints matter early.</h2><h3>1. Foundation and level</h3><p>Follow the sauna manufacturer’s base/foundation requirements. The assembly needs a stable, level support appropriate for its weight and local soil/frost conditions.</p><h3>2. Water management</h3><p>Keep roof runoff, irrigation and standing water away from the structure. Freeze-thaw climates make drainage and site grading especially important.</p><h3>3. Electrical route</h3><p>Plan conductor route, disconnects and service capacity with a licensed electrician before final placement of an electric-heated sauna.</p><h3>4. Access</h3><p>Account for crate/panel delivery, assembly clearances and future heater service access.</p><h3>5. Weather exposure</h3><p>Wind-driven rain, snow load, sun exposure and freeze cycles vary substantially by site. Use the manufacturer’s exterior-treatment and maintenance instructions.</p></div></section>'''+footer())
write('guides/insulation/index.html',head('Outdoor Sauna Insulation & Glass Planning','How insulation and glass affect effective sauna volume and heater sizing.','/guides/insulation/')+nav()+'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Thermal envelope</div><h1>Glass looks great. The heater still has to cover the loss.</h1></div></section><section class="section"><div class="wrap editorial"><p>Heater manufacturers explicitly account for glass and other uninsulated surfaces because they increase the heat load relative to insulated timber walls. Use the heater-sizing tool to convert those surfaces into an effective planning volume, then verify against the exact manufacturer model.</p><a class="btn dark" href="/heater-sizing/">Open heater sizing tool</a></div></section>'''+footer())
write('guides/electrical/index.html',head('Outdoor Sauna Electrical Planning','Electrical planning considerations for outdoor electric traditional saunas.','/guides/electrical/')+nav()+'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Electrical planning</div><h1>Heater kW is an energy number—not a wiring plan.</h1></div></section><section class="section"><div class="wrap editorial"><p>The cost calculator can estimate kWh, but breaker size, conductor size, controls, disconnects, GFCI requirements and permitted installation depend on the exact heater, control package, jurisdiction and manufacturer instructions.</p><div class="callout">Use a qualified electrician and the exact current heater manual for final electrical design.</div><p><a class="btn dark" href="/operating-cost/">Estimate energy cost</a></p></div></section>'''+footer())

# methodology
method=head('Methodology — Outdoor Sauna Climate Index','Data sources, formulas and limitations for the Outdoor Sauna Climate Index.','/methodology/')+nav()+f'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Methodology</div><h1>How the index is built.</h1></div></section><section class="section"><div class="wrap editorial"><h2>Climate baseline</h2><p>The automated updater targets NOAA/NCEI 1991–2020 Monthly Climate Normals using the NCEI Access Data Service. NOAA describes U.S. Climate Normals as official 30-year averages and statistics for temperature, precipitation and other variables.</p><h2>Electricity</h2><p>The updater retrieves the latest available monthly residential electricity price by state from the U.S. Energy Information Administration retail-sales API.</p><h2>Planning Load Score</h2><p>The 0–100 score is a proprietary comparative index. It weights January normal minimum temperature (48%), number of months with normal minimum temperature below freezing (22%), annual precipitation exposure (10%) and residential electricity price (20%). It is not a forecast of sauna performance.</p><h2>Standardized operating-cost scenario</h2><p>City comparisons use a 9 kW electric heater, climate-adjusted warm-up full-load-equivalent hours and a 60% full-load-equivalent assumption during a one-hour session. These assumptions create consistent comparisons; they are not a promise of actual consumption.</p><h2>Freshness</h2><p>The GitHub workflow runs weekly. EIA rates can change as new monthly data are published. NOAA climate normals are intentionally long-term baselines; the updater also stores recent observation context when the matching station returns usable daily data.</p><h2>Limits</h2><p>This site does not replace manufacturer sizing, structural design, electrical engineering, permitting or local building requirements. City-level values use nearby climate stations and state-level electricity rates rather than a specific property or utility tariff.</p><p class="source-list"><a href="https://www.ncei.noaa.gov/products/land-based-station/us-climate-normals" rel="nofollow">NOAA U.S. Climate Normals →</a><br><a href="https://www.ncei.noaa.gov/support/access-data-service-api-user-documentation" rel="nofollow">NCEI Access Data Service →</a><br><a href="https://www.eia.gov/opendata/browser/electricity/retail-sales" rel="nofollow">EIA retail electricity data →</a></p></div></section>'''+footer()
write('methodology/index.html',method)

# data download
write('data-download/index.html',head('Download Outdoor Sauna Climate Index Data','Download the Outdoor Sauna Climate Index in CSV or JSON for analysis and citation.','/data-download/')+nav()+'''<section class="city-hero"><div class="wrap"><div class="eyebrow">Open data</div><h1>Download the index.</h1><p>Publishers and analysts may cite the OutdoorSteamSauna.com Outdoor Sauna Climate Index with attribution and a link to the methodology or dataset page.</p></div></section><section class="section"><div class="wrap grid"><div class="card" style="grid-column:span 6"><h3>CSV</h3><p>Flat city-level table for spreadsheets and analysis.</p><a class="btn dark" href="/data/outdoor-sauna-index.csv">Download CSV</a></div><div class="card" style="grid-column:span 6"><h3>JSON</h3><p>City records including monthly climate details and source metadata.</p><a class="btn dark" href="/data/cities.json">Download JSON</a></div></div></section>'''+footer())

# one and only InHouse outbound link
write('recommended-retailer/index.html',head('Recommended Outdoor Sauna Retailer','Our recommended retail source for premium outdoor traditional sauna kits.','/recommended-retailer/')+nav()+'''<section class="city-hero"><div class="wrap retailer"><div class="eyebrow">Recommended retailer</div><h1>Where to shop for an outdoor traditional sauna.</h1><p>The Climate Index and planning tools are intentionally separate from commerce. For readers who have finished the planning stage and want to compare premium outdoor sauna kits, we recommend one retailer.</p></div></section><section class="section"><div class="wrap retailer"><div class="box"><h2>InHouse Wellness</h2><p>InHouse Wellness carries a broad selection of outdoor traditional sauna formats, including barrel, cabin and larger outdoor kits from multiple sauna manufacturers. That breadth makes it useful when you want to compare sizes, woods, heater configurations and price points in one place.</p><p><b>Why it is the recommended destination:</b> broad outdoor selection, traditional-sauna focus within the collection, and specialist home-wellness support.</p><a class="btn primary" href="https://inhousewellness.com/collections/outdoor-saunas">Browse outdoor saunas at InHouse Wellness →</a></div><p class="data-note">Commercial disclosure: OutdoorSteamSauna.com may have a business relationship with the recommended retailer. The climate rankings and calculations do not use retailer compensation as an input.</p></div></section>'''+footer())

# city pages
for c in cities:
 m=c['metrics']; mon=c['monthly']; max_t=max(x['tavg_f'] for x in mon); min_t=min(x['tavg_f'] for x in mon); span=max(1,max_t-min_t)
 bars=''.join(f'''<div class="monthbar" style="height:{25+120*(x['tavg_f']-min_t)/span:.0f}px" title="{x['tavg_f']}°F"><span>{['J','F','M','A','M','J','J','A','S','O','N','D'][x['month']-1]}</span></div>''' for x in mon)
 recent=''
 if c.get('recent'):
  recent=f'''<div class="metric"><small>RECENT AVG</small><b>{c['recent'].get('avg_f','—')}°F</b><span class="muted">{c['recent'].get('delta_f','—')}°F vs normal</span></div>'''
 page=head(f"Outdoor Sauna Guide for {c['city']}, {c['state']}",f"Outdoor sauna climate planning, winter conditions and operating-cost estimates for {c['city']}, {c['state']}.",f"/cities/{c['slug']}/")+nav()+f'''<section class="city-hero"><div class="wrap"><div class="eyebrow">City profile · #{c['rank']} planning load</div><h1>{esc(c['city'])}, {c['state']}</h1><p>{m['label']}. A standardized data profile for planning an outdoor traditional sauna in the {esc(c['city'])} area.</p></div></section><section class="section"><div class="wrap"><div class="metric-grid"><div class="metric"><small>LOAD SCORE</small><b>{m['score']}/100</b><span class="muted">comparative index</span></div><div class="metric"><small>JAN NORMAL LOW</small><b>{m['jan_tmin_f']}°F</b><span class="muted">climate baseline</span></div><div class="metric"><small>POWER RATE</small><b>{m['rate_cents']}¢</b><span class="muted">per kWh</span></div><div class="metric"><small>9 kW SESSION</small><b>${m['session_cost_9kw']:.2f}</b><span class="muted">standard scenario</span></div>{recent}</div></div></section><section class="section"><div class="wrap grid"><div class="card" style="grid-column:span 8"><div class="eyebrow">Monthly normal temperature</div><h2>Seasonal thermal profile</h2><div class="monthly">{bars}</div></div><div class="card" style="grid-column:span 4"><h3>Site exposure</h3><p><b>{m['freeze_months']}</b> months with normal minimum below 32°F</p><p><b>{m['annual_snow_in']} in</b> modeled/observed normal snow in the current record</p><p><b>{m['annual_prcp_in']} in</b> annual precipitation</p><p class="data-note">Climate source: {esc(c['climate_source'])}<br>Station: {esc(c.get('station') or 'pending live refresh')}</p></div></div></section><section class="section"><div class="wrap editorial"><h2>What this means for an outdoor sauna project</h2><p>In colder locations, the enclosure starts farther from sauna temperature, making insulation, door discipline, glass area and heater sizing more consequential. The city score is designed to compare that planning burden—not to dictate a particular heater.</p><p>At the current state electricity input, the standardized 9 kW scenario is approximately <b>${m['session_cost_9kw']:.2f} per session</b>, or about <b>${m['annual_cost_3x_week']}/year</b> at three sessions per week. Your actual use can differ materially.</p><p><a class="btn dark" href="/heater-sizing/">Calculate effective room volume</a> <a class="btn" href="/recommended-retailer/">Where to buy an outdoor sauna</a></p></div></section>'''+footer()
 write(f"cities/{c['slug']}/index.html",page)

# state pages
for st,cs in states.items():
 cs=sorted(cs,key=lambda x:x['metrics']['score'],reverse=True); avg=round(sum(x['metrics']['score'] for x in cs)/len(cs),1); rate=round(sum(x['metrics']['rate_cents'] for x in cs)/len(cs),2)
 trs=''.join(f'''<tr><td><a href="/cities/{x['slug']}/">{esc(x['city'])}</a></td><td>{x['metrics']['score']}</td><td>{x['metrics']['jan_tmin_f']}°F</td><td>${x['metrics']['session_cost_9kw']:.2f}</td></tr>''' for x in cs)
 page=head(f"Outdoor Sauna Climate Guide — {cs[0]['state_name']}",f"Outdoor sauna climate and operating-cost profiles for indexed metros in {cs[0]['state_name']}.",f"/states/{slug(cs[0]['state_name'])}/")+nav()+f'''<section class="city-hero"><div class="wrap"><div class="eyebrow">State profile</div><h1>{esc(cs[0]['state_name'])}</h1><p>{len(cs)} indexed metro{'s' if len(cs)!=1 else ''} · average planning-load score {avg} · electricity input {rate}¢/kWh</p></div></section><section class="section"><div class="wrap"><table><thead><tr><th>Metro</th><th>Score</th><th>Jan low</th><th>9 kW/session</th></tr></thead><tbody>{trs}</tbody></table></div></section>'''+footer()
 write(f"states/{slug(cs[0]['state_name'])}/index.html",page)

# CSV dataset
